def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    live_prev_bids = []
    rich_threat = False
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120 and opp.get('hp', 0) > 0:
                rich_threat = True
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    live_prev_bids.append(float(bid))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(live_prev_bids) if live_prev_bids else 0.0
    avg_prev = sum(live_prev_bids) / len(live_prev_bids) if live_prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water == 1:
        urgency += 0.45
    urgency += 0.55 * scarcity
    if day >= 8:
        urgency += 0.2

    if hp <= 2 or no_water >= 2:
        bid = max(58.0, highest_prev + 2.0)
        if rich_threat and scarcity > 0.6:
            bid = max(bid, 92.0)
        return float(min(budget, bid))

    if scarcity < 0.25 and hp >= 5 and no_water == 0:
        return float(min(budget, 16.0))

    if highest_prev >= 120:
        if urgency < 0.9:
            bid = 22.0 + 10.0 * scarcity
        else:
            bid = 72.0 + 18.0 * scarcity
    elif highest_prev >= 70:
        if urgency < 0.7:
            bid = max(28.0, avg_prev * 0.55)
        else:
            bid = min(highest_prev + 3.0, 88.0)
    else:
        bid = 34.0 + 18.0 * scarcity + 8.0 * urgency

    if rich_threat and scarcity > 0.7 and urgency >= 0.8:
        bid = max(bid, 85.0)

    reserve_floor = 20.0 if day < 8 else 0.0
    bid = min(bid, max(0.0, budget - reserve_floor))
    bid = max(0.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)

    # If no opponents alive, bid to meet requirement safely
    if not alive_opps:
        target = DAILY_SALARY * 0.45
        return min(my_status['budget'], target)

    # Read yesterday bids to infer pressure level
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        pbid = prev.get('bid', None)
        if pbid is not None:
            try:
                yesterday_bids.append(float(pbid))
            except Exception:
                pass

    # Pressure heuristic from yesterday
    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    second_highest = 0.0
    if yesterday_bids:
        sorted_b = sorted(yesterday_bids)
        if len(sorted_b) >= 2:
            second_highest = sorted_b[-2]

    # Budget/hp urgency
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    # Supply scarcity: lower supply increases chance of losing water if we underbid
    # Normalize scarcity factor between 0 and 1
    if MAX_SUPPLY == MIN_SUPPLY:
        scarcity = 0.5
    else:
        scarcity = (float(MAX_SUPPLY) - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # If Cindy-style overspending likely occurred (very high highest_prev), avoid bidding to win by matching.
    # Instead, bid a fraction based on scarcity and our urgency.
    # Also, if our hp/no_water_days are critical, we must bid higher.
    critical = (hp <= 2) or (no_water_days >= 2)

    # Base bid: enough to compete when supply is low, but not always matching the top bidder.
    # Use highest_prev as a ceiling reference, but don't chase it fully.
    if highest_prev >= DAILY_SALARY * 1.4:
        # High pressure: likely someone (e.g., Cindy) is strong. Bid around the second-highest + small increment.
        # If we are critical, we may need to approach highest_prev fractionally.
        if critical:
            bid = 0.92 * highest_prev
        else:
            bid = 0.55 * highest_prev + 0.25 * second_highest
    else:
        # Moderate pressure: bid near the upper-middle.
        if critical:
            bid = DAILY_SALARY * (0.85 + 0.15 * scarcity)
        else:
            bid = DAILY_SALARY * (0.55 + 0.25 * scarcity)

    # Scarcity adjustment
    if not critical:
        bid = bid * (0.9 + 0.2 * scarcity)

    # Ensure we don't bid beyond budget
    if bid > budget:
        bid = budget

    # Safety minimum: if we have budget, keep a reasonable bid to avoid prolonged no-water days.
    # (If budget is very low, just spend what we have.)
    min_reasonable = DAILY_SALARY * 0.25
    if budget <= min_reasonable:
        return budget

    if bid < min_reasonable:
        bid = min_reasonable

    # Final clamp
    if bid > budget:
        bid = budget
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace')
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    days_remaining = EPISODE_DAYS - day_context['day']

    bid_amount = 0.0

    # In this scenario (supply 15-25, WATER_REQ 13), only one agent gets their full water requirement.
    # It's a winner-take-all situation for the water.

    if my_hp <= 2: # Critical HP, must win
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            bid_amount = max(highest_prev_bid + 5.0, DAILY_SALARY * 0.95)
        else:
            bid_amount = DAILY_SALARY * 0.9
    elif my_hp == 3: # Moderate HP, need water soon but can afford some risk
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            bid_amount = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.75)
        else:
            bid_amount = DAILY_SALARY * 0.7
    else: # High HP (4 or 5), can afford to miss a day
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            # If opponents are bidding very high, and I have good HP and days left, consider backing off to save budget
            if highest_prev_bid > DAILY_SALARY * 0.8 and my_hp >= 4 and days_remaining > 2:
                bid_amount = DAILY_SALARY * 0.4
            else:
                bid_amount = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.55)
        else:
            bid_amount = DAILY_SALARY * 0.5

    bid_amount = min(bid_amount, my_budget)
    bid_amount = max(bid_amount, 1.0)

    return bid_amount
